    # ------------------------------------------------------------ Kart sahibi

    def holder_cards(
        self,
        *,
        query: Optional[T.HolderCardsQuery] = None,
        timeout: Optional[float] = None,
        max_retries: Optional[int] = None,
    ) -> T.HolderCardsData:
        """Kartlarım

        Hesabın bütün işletmelerdeki kartları: doğrulanmış adreslerinizle verilen kartlar ve hesaba bağlantısıyla eklenenler. Bakiye, ödül durumu, seviye, renkler ve kasada okutulacak değer; kartın QR kodunu `qrValue` ile kendiniz çizin.
        **Sıra** web cüzdanının Kartlarım sırasıdır; kartlar işletme işletme gelir:
        1. yıldızlı kartı olan işletmeler, kişinin kendi sırasında (`GET /v1/holder/favorites`, `PUT /v1/holder/favorites/order`);
        2. ödülü hazır olanlar;
        3. son zamanlarda sık gidilenler: son 90 günün ziyaretleri, yenisi daha ağır (her ziyaret bugün 1, 30 gün önce ½, 60 gün önce ¼ sayılır);
        4. en yeni kart;
        bütün kartları bitmiş işletmeler en sonda. Bir işletmenin içinde önce etkin kartlar, en eskisi önce. Konuma göre sıralamak uygulamanın işidir: her kart işletmesinin şubelerini (`places`) taşır, konum sunucuya gönderilmez; yıldızlılar yine en başta kalsın.
        **Listeden kaldırılan kartlar** (`hidden: true`) bu sıranın ardından, en sonda gelir ve sırayı etkilemez: Kartlarım'ı ve işletme görünümünü onları atlayarak çizin; bütün kartları kaldırılmış işletme Kartlarım'da görünmez. Eski kartlar biten kartlardır (`ended: true`), kaldırılmış olsun olmasın: en son biten önce (`endedAt`, kaydı olmayan en sonda).
        `merchant` (kartlardaki `merchantSlug`) yalnız o işletmenin kartlarını işletme görünümünün sırasıyla verir, listeden kaldırılanlar sonda.

        **Kimlik:** kart sahibi oturumu.

        ``GET /v1/holder/cards``

        API referansı: https://rewloy.com/gelistiriciler/api#op-holderCards
        """
        return cast(
            "T.HolderCardsData",
            self._call(
                "holderCards",
                query=query,
                timeout=timeout,
                max_retries=max_retries,
            ),
        )

    def add_holder_card(
        self,
        *,
        body: T.AddHolderCardBody,
        timeout: Optional[float] = None,
        max_retries: Optional[int] = None,
    ) -> T.AddHolderCardData:
        """Kartı bağlantısıyla ekle

        Kartın özel bağlantısındaki (`/p/{serial}?k=…`, e-postadaki "Kartımı aç") seri numarası ve `k` değeriyle kart hesaba eklenir. Web cüzdanındaki "Rewloy Cüzdan'a ekle"nin karşılığıdır.
        - Anahtar kartı verir, arkasındaki kişiyi vermez. Kart `GET /v1/holder/cards` listesine girer; hesabın doğrulanmış bir adresiyle ulaşılmayan bir kayıttaysa `personId` alanı `null` gelir ve o kaydın tercihleri, bilgileri ya da verileri bu hesaptan yönetilmez.
        - Yanlış anahtar ile bilinmeyen seri numarası aynı `404 PASS_NOT_FOUND` yanıtını alır.
        - `added: false` (`200`): kart bu hesaba zaten bağlıydı. Yeni bağlanan kart `201` ile döner.
        - IP başına 15 dakikada 20 deneme, web cüzdanının "Rewloy Cüzdan'a ekle" düğmesiyle ortak.

        **Kimlik:** kart sahibi oturumu.

        ``POST /v1/holder/cards``

        API referansı: https://rewloy.com/gelistiriciler/api#op-addHolderCard
        """
        return cast(
            "T.AddHolderCardData",
            self._call(
                "addHolderCard",
                body=body,
                timeout=timeout,
                max_retries=max_retries,
            ),
        )

