    def holder_card_events(
        self,
        serial: str,
        *,
        timeout: Optional[float] = None,
        max_retries: Optional[int] = None,
        reconnect: bool = True,
        idle_timeout: Optional[float] = None,
    ) -> EventStream:
        """Kart değişince haber (SSE)

        Kartta bir şey değişince (damga, ödül, bakiye, mesaj) `event: changed` satırı gelir; kartı yeniden okuyun (`GET /v1/holder/cards/{serial}`). 25 saniyede bir `: hb` satırı. `fetch` ile akış okuyun. IP başına en fazla 12 açık bağlantı. Oturum kapanırsa (çıkış, cihaz kaldırıldı, hesap silindi) akış en geç bir dakika içinde sunucu tarafından biter; yeniden bağlanmak `401 TOKEN_INVALID` alır.

        **Kimlik:** kart sahibi oturumu.

        ``GET /v1/holder/cards/{serial}/events``

        API referansı: https://rewloy.com/gelistiriciler/api#op-holderCardEvents
        """
        return self._open(
            "holderCardEvents",
            path={"serial": serial},
            timeout=timeout,
            max_retries=max_retries,
            reconnect=reconnect,
            idle_timeout=idle_timeout,
        )

